 	constructor(message: string, options: ExecutionBaseErrorOptions = {}) {
 		super(message, options);

-		this.name = this.constructor.name;
+		// Define `name` as an own property instead of assigning it: if
+		// `Error.prototype` is frozen, the inherited `name` is non-writable and a
+		// plain assignment throws in strict mode (the "override mistake").
+		Object.defineProperty(this, 'name', {
+			value: this.constructor.name,
+			writable: true,
+			enumerable: true,
+			configurable: true,
+		});
