--- /dev/null
+++ b/packages/workflow/test/errors/execution-base.error.test.ts
@@ -0,0 +1,58 @@
+import { ExecutionBaseError } from '../../src/errors/abstract/execution-base.error';
+import { NodeOperationError } from '../../src/errors/node-operation.error';
+import { WorkflowOperationError } from '../../src/errors/workflow-operation.error';
+
+class TestExecutionError extends ExecutionBaseError {}
+
+describe('ExecutionBaseError', () => {
+	it('should set name to the constructor name as an own property', () => {
+		const error = new TestExecutionError('test');
+
+		expect(error.name).toBe('TestExecutionError');
+		expect(Object.getOwnPropertyDescriptor(error, 'name')).toEqual({
+			value: 'TestExecutionError',
+			writable: true,
+			enumerable: true,
+			configurable: true,
+		});
+	});
+
+	describe('when Error.prototype is frozen', () => {
+		const original = Object.getOwnPropertyDescriptor(Error.prototype, 'name')!;
+
+		beforeEach(() => {
+			// Simulate a frozen Error.prototype for the `name` property, without
+			// irreversibly freezing the prototype for the rest of the test run.
+			Object.defineProperty(Error.prototype, 'name', { ...original, writable: false });
+		});
+
+		afterEach(() => {
+			Object.defineProperty(Error.prototype, 'name', original);
+		});
+
+		it('should construct execution errors without throwing', () => {
+			const error = new TestExecutionError('test');
+			expect(error.name).toBe('TestExecutionError');
+			expect(error.message).toBe('test');
+		});
+
+		it('should allow subclasses to reassign name', () => {
+			const error = new WorkflowOperationError('test');
+			expect(error.name).toBe('WorkflowOperationError');
+		});
+
+		it('should construct node errors', () => {
+			const node = {
+				id: '1',
+				name: 'Node',
+				type: 'n8n-nodes-base.noOp',
+				typeVersion: 1,
+				position: [0, 0] as [number, number],
+				parameters: {},
+			};
+			const error = new NodeOperationError(node, 'boom');
+			expect(error.name).toBe('NodeOperationError');
+			expect(error.message).toBe('boom');
+		});
+	});
+});
